import React from 'react';
import {configure as configureMarkdownEditor, MarkdownEditorView, useMarkdownEditor} from '@gravity-ui/markdown-editor';
import type {MarkdownEditorInstance} from '@gravity-ui/markdown-editor';

import './MarkdownField.css';

configureMarkdownEditor({lang: 'ru'});

export interface MarkdownFieldProps {
  /** Receives the editor instance so the form can read `editor.getValue()` on submit. */
  onReady?: (editor: MarkdownEditorInstance) => void;
  initialValue?: string;
}

/**
 * Markdown input with live formatting: in WYSIWYG mode the markup typed by the user
 * (`# `, `**bold**`, `- `, `> `, ...) is rendered immediately. The toolbar switcher
 * also allows moving to raw markup mode with a side-by-side preview.
 */
export const MarkdownField = ({onReady, initialValue = ''}: MarkdownFieldProps) => {
  const renderPreview = React.useCallback(() => null, []);
  void renderPreview;

  const editor = useMarkdownEditor({
    md: {html: false, linkify: true},
    initial: {markup: initialValue, mode: 'wysiwyg'},
  });

  React.useEffect(() => {
    onReady?.(editor);
  }, [editor, onReady]);

  return (
    <div className="markdown-field">
      <MarkdownEditorView editor={editor} stickyToolbar={false} />
    </div>
  );
};
